    tips: { tip1: "Notice the repeated pattern: wait → act → courage follows.", tip2: "Examples are used to prove a general claim.", tip3: "Look for contrast words like 'not before, after'.", tip4: "The last paragraph is a direct call to action.", tip5: "Underline phrases you can use in conversation.", tip6: "After reading, ask: What is one small step I could take?", tip7: "Summarize the main idea in your own words." },
    teacherGuide: { objective: "Students will read a motivational passage about courage and practice inference and personal connection.", warmUp: ["What does courage mean to you?", "Name one time you were brave.", "Do you wait to feel ready before acting?"], keyVocabulary: ["courage", "willingness", "doubt", "repetition"], grammarFocus: ["Comparative structures", "Modal verbs", "Noun phrases"], readingStrategy: "Finding the thesis and using examples.", discussionQuestions: ["Is waiting to feel ready always a bad idea?", "What makes it hard to take the first step?", "How does repetition build confidence?"], debateQuestion: "Should schools teach students to act before they feel ready?", speakingExtension: "Describe a time you took a small brave step.", writingExtension: "Write 100–150 words about one small step you want to take.", lessonPlan: [{ time: "5 min", activity: "Warm-up discussion" }, { time: "10 min", activity: "First reading for gist" }, { time: "8 min", activity: "Vocabulary focus" }, { time: "10 min", activity: "Comprehension questions" }, { time: "7 min", activity: "Personal connection discussion" }] },
