    teacherGuide: { objective: "Students will read a modern-issues passage, identify argument structure, and discuss digital habits.", warmUp: ["How many hours do you spend on your phone each day?", "What is the last long article you read?", "Do you feel distracted by notifications?"], keyVocabulary: ["notification", "informed", "clarity", "defense"], grammarFocus: ["Passive voice", "Modal verbs", "Abstract nouns"], readingStrategy: "Identifying paradox and evaluating solutions.", discussionQuestions: ["Does social media help or harm understanding?", "What is one digital habit you would like to change?", "How can schools help students focus better?"], debateQuestion: "Should schools ban phones during class to improve focus?", speakingExtension: "Describe your ideal day with less digital noise.", writingExtension: "Write 120–170 words about one habit to reduce digital noise.", lessonPlan: [{ time: "5 min", activity: "Warm-up poll" }, { time: "10 min", activity: "First reading for gist" }, { time: "8 min", activity: "Vocabulary and grammar" }, { time: "10 min", activity: "Comprehension and inference questions" }, { time: "7 min", activity: "Discussion about digital habits" }] },
