    teacherGuide: { objective: "Students will read a mindfulness passage, identify claims and contrasts, and discuss quiet habits.", warmUp: ["Do you like silence? Why or why not?", "When do you feel most peaceful?", "How much quiet time do you have each day?"], keyVocabulary: ["silence", "loneliness", "creativity", "available"], grammarFocus: ["Be + adjective", "Comparative structures", "Imperatives"], readingStrategy: "Finding the main claim and noticing contrast.", discussionQuestions: ["Is silence easy or difficult in modern life?", "What makes silence valuable?", "How can people create more quiet time?"], debateQuestion: "Should schools include quiet time in the daily schedule?", speakingExtension: "Describe your favorite quiet place.", writingExtension: "Write 80–120 words about a quiet moment that helped you.", lessonPlan: [{ time: "5 min", activity: "Warm-up discussion" }, { time: "8 min", activity: "First reading for gist" }, { time: "8 min", activity: "Vocabulary and grammar" }, { time: "10 min", activity: "Comprehension questions" }, { time: "7 min", activity: "Quiet practice and discussion" }] },
